<script setup>
/* eslint-disable vue/no-bare-strings-in-template */
import { computed, onMounted, reactive, ref } from 'vue';
import { contractsAPI, salesOrdersAPI } from 'dashboard/api/crm/commercialCycle';
import { useAlert } from 'dashboard/composables';
const rows=ref([]); const orders=ref([]); const loading=ref(false); const selected=ref(null); const showForm=ref(false); const saving=ref(false);
const form=reactive({sales_order_id:'',status:'draft',starts_on:'',ends_on:'',term_months:12,renewal_type:'automatic',adjustment_index:'IPCA',monthly:'0',one_time:'0',notes:''});
const cents=v=>Math.round((Number(String(v).replace(',','.'))||0)*100); const money=v=>new Intl.NumberFormat('pt-BR',{style:'currency',currency:'BRL'}).format((Number(v)||0)/100);
const stats=computed(()=>({count:rows.value.length,active:rows.value.filter(r=>r.status==='active').length,mrr:rows.value.filter(r=>r.status==='active').reduce((s,r)=>s+(Number(r.monthly_cents)||0),0)}));
const load=async()=>{loading.value=true;try{const [c,o]=await Promise.all([contractsAPI.list(),salesOrdersAPI.list()]);rows.value=c.data||[];orders.value=o.data||[];}finally{loading.value=false;}};
const save=async()=>{saving.value=true;try{await contractsAPI.create({contract:{...form,monthly_cents:cents(form.monthly),one_time_cents:cents(form.one_time)}});showForm.value=false;await load();useAlert('Contrato criado com sucesso.');}catch(e){useAlert(e.response?.data?.errors?.join(', ')||'Não foi possível criar o contrato.');}finally{saving.value=false;}};
const downloadPdf=async()=>{try{const response=await contractsAPI.pdf(selected.value.id);const url=URL.createObjectURL(new Blob([response.data],{type:'application/pdf'}));const link=document.createElement('a');link.href=url;link.download=`${selected.value.contract_number||'contrato'}.pdf`;link.click();URL.revokeObjectURL(url);}catch(e){useAlert(e.response?.data?.errors?.join(', ')||'Não foi possível gerar o PDF do contrato.');}};
onMounted(load);
</script>
<template><div class="h-full overflow-auto bg-n-surface-1 p-4 sm:p-6"><header class="mb-5 flex flex-wrap items-center justify-between gap-3"><div class="flex items-center gap-3"><span class="grid size-11 place-content-center rounded-2xl bg-blue-50 text-blue-700"><i class="i-lucide-file-lock-2 size-5" /></span><div><h2 class="text-2xl font-bold">Contratos</h2><p class="text-sm text-n-slate-9">Vigência, renovação, reajustes e recorrência dos clientes.</p></div></div><button class="rounded-xl bg-n-brand px-4 py-2.5 text-sm font-semibold text-white" @click="showForm=true">+ Novo contrato</button></header><section class="mb-4 grid gap-3 sm:grid-cols-3"><article class="rounded-2xl border border-n-weak bg-white p-4"><p class="text-xs text-n-slate-9">Contratos</p><strong class="text-2xl">{{ stats.count }}</strong></article><article class="rounded-2xl border border-n-weak bg-white p-4"><p class="text-xs text-n-slate-9">Vigentes</p><strong class="text-2xl text-emerald-700">{{ stats.active }}</strong></article><article class="rounded-2xl border border-n-weak bg-white p-4"><p class="text-xs text-n-slate-9">MRR contratado</p><strong class="text-xl">{{ money(stats.mrr) }}</strong></article></section><div class="overflow-hidden rounded-2xl border border-n-weak bg-white"><table class="w-full text-sm"><thead class="bg-n-alpha-2 text-left text-xs uppercase text-n-slate-9"><tr><th class="p-3">Contrato / Cliente</th><th class="p-3">Negócio / Venda</th><th class="p-3">Vigência</th><th class="p-3">Mensal</th><th class="p-3">Status</th></tr></thead><tbody class="divide-y divide-n-weak"><tr v-if="loading"><td colspan="5" class="p-10 text-center">Carregando…</td></tr><tr v-for="row in rows" :key="row.id" class="cursor-pointer hover:bg-n-alpha-2" @click="selected=row"><td class="p-3"><strong>{{ row.contract_number || `#${row.id}` }}</strong><p class="text-xs text-n-slate-9">{{ row.contact?.name || '—' }}</p></td><td class="p-3">{{ row.deal?.title || '—' }}<p class="text-xs text-n-slate-9">{{ row.sales_order?.order_number || '—' }}</p></td><td class="p-3">{{ row.starts_on || '—' }} → {{ row.ends_on || '—' }}</td><td class="p-3 font-semibold">{{ money(row.monthly_cents) }}</td><td class="p-3"><span class="rounded-full bg-blue-50 px-2 py-1 text-xs font-semibold text-blue-700">{{ row.status }}</span></td></tr><tr v-if="!loading&&!rows.length"><td colspan="5" class="p-10 text-center text-n-slate-9">Nenhum contrato ainda.</td></tr></tbody></table></div>
<Teleport to="body"><div v-if="showForm" class="fixed inset-0 z-[90] grid place-content-center bg-black/45 p-4" @click.self="showForm=false"><form class="w-full max-w-2xl rounded-2xl bg-white p-6" @submit.prevent="save"><div class="flex justify-between"><div><h3 class="text-xl font-bold">Novo contrato</h3><p class="text-sm text-n-slate-9">Crie a partir de um Pedido/Venda confirmado.</p></div><button type="button" class="i-lucide-x" @click="showForm=false" /></div><div class="mt-5 grid gap-3 md:grid-cols-2"><label class="text-sm font-semibold md:col-span-2">Pedido<select v-model="form.sales_order_id" required class="mt-1 w-full rounded-lg border border-n-weak px-3 py-2"><option value="">Selecione</option><option v-for="order in orders" :key="order.id" :value="order.id">{{ order.order_number }} — {{ order.contact?.name }} — {{ money(order.total_cents) }}</option></select></label><label class="text-sm">Início<input v-model="form.starts_on" type="date" class="mt-1 w-full rounded-lg border border-n-weak px-3 py-2" /></label><label class="text-sm">Fim<input v-model="form.ends_on" type="date" class="mt-1 w-full rounded-lg border border-n-weak px-3 py-2" /></label><label class="text-sm">Vigência (meses)<input v-model.number="form.term_months" type="number" min="1" class="mt-1 w-full rounded-lg border border-n-weak px-3 py-2" /></label><label class="text-sm">Status<select v-model="form.status" class="mt-1 w-full rounded-lg border border-n-weak px-3 py-2"><option value="draft">Rascunho</option><option value="awaiting_signature">Aguardando assinatura</option><option value="active">Vigente</option></select></label><label class="text-sm">Mensalidade (R$)<input v-model="form.monthly" type="number" min="0" step="0.01" class="mt-1 w-full rounded-lg border border-n-weak px-3 py-2" /></label><label class="text-sm">Valor único (R$)<input v-model="form.one_time" type="number" min="0" step="0.01" class="mt-1 w-full rounded-lg border border-n-weak px-3 py-2" /></label><label class="text-sm">Renovação<select v-model="form.renewal_type" class="mt-1 w-full rounded-lg border border-n-weak px-3 py-2"><option value="automatic">Automática</option><option value="manual">Manual</option></select></label><label class="text-sm">Índice de reajuste<input v-model="form.adjustment_index" class="mt-1 w-full rounded-lg border border-n-weak px-3 py-2" /></label><label class="text-sm md:col-span-2">Observações<textarea v-model="form.notes" rows="3" class="mt-1 w-full rounded-lg border border-n-weak px-3 py-2" /></label></div><div class="mt-5 flex justify-end gap-2"><button type="button" class="rounded-lg border border-n-weak px-4 py-2" @click="showForm=false">Cancelar</button><button :disabled="saving" class="rounded-lg bg-n-brand px-4 py-2 font-semibold text-white disabled:opacity-50">Criar contrato</button></div></form></div><div v-if="selected" class="fixed inset-0 z-[90] flex justify-end bg-black/40" @click.self="selected=null"><aside class="h-full w-full max-w-lg bg-white p-6"><div class="flex justify-between"><div><p class="text-xs uppercase text-n-slate-9">Contrato</p><h3 class="text-xl font-bold">{{ selected.contract_number }}</h3><p class="text-sm text-n-slate-9">{{ selected.contact?.name }}</p></div><button class="i-lucide-x" @click="selected=null" /></div><dl class="mt-6 grid grid-cols-2 gap-4 rounded-xl border border-n-weak p-4 text-sm"><div><dt class="text-n-slate-9">Status</dt><dd class="font-semibold">{{ selected.status }}</dd></div><div><dt class="text-n-slate-9">Vigência</dt><dd class="font-semibold">{{ selected.term_months || '—' }} meses</dd></div><div><dt class="text-n-slate-9">Mensalidade</dt><dd class="font-semibold">{{ money(selected.monthly_cents) }}</dd></div><div><dt class="text-n-slate-9">Valor único</dt><dd class="font-semibold">{{ money(selected.one_time_cents) }}</dd></div><div><dt class="text-n-slate-9">Renovação</dt><dd class="font-semibold">{{ selected.renewal_type || '—' }}</dd></div><div><dt class="text-n-slate-9">Reajuste</dt><dd class="font-semibold">{{ selected.adjustment_index || '—' }}</dd></div></dl><button class="mt-6 inline-flex w-full items-center justify-center gap-2 rounded-xl bg-n-brand px-4 py-3 text-sm font-semibold text-white" @click="downloadPdf"><i class="i-lucide-download size-4" />Baixar PDF do contrato</button></aside></div></Teleport></div></template>
